#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/recursive_improvement_v12_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/recursive_improvement_controller.py
echo "" | base64 -d > scripts/companyos_recursive_ctl
chmod +x scripts/companyos_recursive_ctl
echo "" | base64 -d > tests/test_recursive_improvement_v12.py

echo "" | base64 -d > "$PREFIX/tmp/companyos_recursive_v12_patch.py"
python "$PREFIX/tmp/companyos_recursive_v12_patch.py"
rm -f "$PREFIX/tmp/companyos_recursive_v12_patch.py"

echo "[1/8] Compile"
python -m py_compile companyos/runtime/recursive_improvement_controller.py companyos/runtime/service_supervisor.py tests/test_recursive_improvement_v12.py

echo "[2/8] Safety/loop tests"
python -m unittest tests.test_recursive_improvement_v12 -v

echo "[3/8] Existing inventory"
scripts/companyos_expandctl inventory || true

echo "[4/8] Run one autonomous recursive cycle"
scripts/companyos_recursive_ctl once | tee .companyos_runtime/recursive_improvement_v12_first_cycle.json || true

echo "[5/8] Show recursive status/history"
scripts/companyos_recursive_ctl status || true
scripts/companyos_recursive_ctl history || true

echo "[6/8] Refresh feedback"
scripts/companyos_feedbackctl once || true

echo "[7/8] Commit/push"
git add companyos/runtime/recursive_improvement_controller.py companyos/runtime/service_supervisor.py scripts/companyos_recursive_ctl tests/test_recursive_improvement_v12.py
git diff --cached --quiet || git commit -m "Add autonomous recursive improvement controller"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[8/8] Restart + verify"
scripts/companyosctl restart || true
sleep 8

echo "===== RECURSIVE CONTROLLER ====="
scripts/companyos_recursive_ctl status || true
echo "===== REQUEST EXECUTOR ====="
scripts/companyos_requestctl status || true
echo "===== COMPOUNDING ====="
scripts/companyos_compoundctl status || true
echo "===== INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== FEEDBACK ====="
scripts/companyos_feedbackctl status || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_AUTONOMOUS_RECURSIVE_IMPROVEMENT_V12=PASS"
